"diversify-research": t => [[150,TC.red],[200,TC.red],[290,TC.blue],[340,TC.blue]].map(([x,c],i)=>bob(techCard(x,135,c,{s:1.5,rot:(i%2?6:-6)}),i*.6)).join("") + `<path d="M245 70v130" stroke="${t}" stroke-opacity=".4" stroke-dasharray="3 5"/><circle cx="245" cy="135" r="12" fill="${t}" class="a-pulse"/>`,
"erect-a-monument": t => `<path d="M220 235L232 70L240 50L248 70L260 235Z" fill="#1a2238" stroke="${t}" stroke-width="2"/><path d="M232 70L248 70M226 150h28M223 195h34" stroke="${t}" stroke-opacity=".5"/>` + `<rect x="150" y="235" width="180" height="10" fill="#1a2238" stroke="${t}" stroke-opacity=".6"/>` + [0,1,2,3,4,5,6,7].map(i=>fly(resTok(80+(i%2)*320,200-i*12,8),i%2?-150:150,-60+i*6,4,i*.5)).join("") + `<circle cx="240" cy="50" r="6" fill="#fff" class="a-pulse"/><path d="M240 50L200 0M240 50L280 0" stroke="${t}" stroke-opacity=".25" stroke-width="6" class="a-pulse"/>`,
