"discover-lost-outposts": t => [[150,140],[330,140]].map(([x,y],i)=>planet(x,y,40,[TR.cul,TR.haz][i])+bob(`<rect x="${x-14}" y="${y-88}" width="28" height="36" rx="3" fill="#121a2e" stroke="${t}" stroke-width="1.5"/><path d="M${x} ${y-80}l8 10-8 10-8-10z" fill="${t}" class="a-pulse"/>`,i)+`<path d="M${x} ${y-52}V${y-40}" stroke="${t}" stroke-dasharray="2 3"/>`).join("") + ship("cruiser",240,70,1.3,t),
"engineer-a-marvel": t => warsun(240,140,2.6,t) + `<path d="M150 230L170 80M330 230L310 80M160 150h160M155 190h170" stroke="#4a5876" stroke-width="2"/>` + [[200,120],[285,165],[220,180]].map(([x,y],i)=>`<g class="a-spark" style="transform-origin:${x}px ${y}px;transform-box:view-box;animation-delay:${i*.4}s"><circle cx="${x}" cy="${y}" r="3" fill="#fff"/><path d="M${x} ${y}l10 -6M${x} ${y}l9 5M${x} ${y}l-3 10" stroke="#ffd27a"/></g>`).join(""),
