"populate-the-outer-rim": t => { let s=grid(240,135,26,RING2,(x,y,q,r)=>{const edge=Math.max(Math.abs(q),Math.abs(r),Math.abs(-q-r))===2;return hex(x,y,24,edge?{fill:mix(t,"#000",.75),stroke:t}:{})}); [[2,-2],[2,0],[0,2]].forEach(([q,r],i)=>{const [x,y]=hxy(q,r,26,240,135);s+=pop(ship("cruiser",x,y,.9,t),i*.7,6)}); return s+`<circle cx="240" cy="135" r="120" fill="none" stroke="${t}" stroke-opacity=".3" stroke-dasharray="3 7" class="a-dash"/>`; },
