"form-galactic-brain-trust": t => { const P=[[100,90],[180,180],[240,80],[310,175],[385,95]]; let s=""; for(let i=0;i<5;i++)for(let j=i+1;j<5;j++) s+=link(...P[i],...P[j],t,(i+j)*.2); return s+P.map(([x,y],i)=>planet(x,y,20,[TC.blue,TC.green,TC.yellow,TC.red,TC.blue][i])+`<circle cx="${x}" cy="${y}" r="28" fill="none" stroke="${t}" class="a-ping"${D(0,i*.4)}/>`).join(""); },
"found-a-golden-age": t => planet(240,250,150,"#e3bd6c",{lights:true}) + `<g stroke="#f0d79a" fill="#2a2210">${[150,180,205,240,268,295,325].map((x,i)=>`<rect x="${x}" y="${120-[20,50,30,80,40,60,25][i]}" width="20" height="${[20,50,30,80,40,60,25][i]+20}"/>`).join("")}</g>` + `<circle cx="240" cy="40" r="22" fill="#ffe7a8" class="a-grow"/>` + [...Array(12)].map((_,i)=>`<path d="M240 40L${f1(240+Math.cos(i*.52)*70)} ${f1(40+Math.sin(i*.52)*70)}" stroke="#ffe7a8" stroke-opacity=".3"/>`).join(""),
"galvanize-the-people": t => [...Array(6)].map((_,i)=>fly(cmdTok(80+i*64,240,15,t),0,-150,4,i*.5)).join("") + [...Array(14)].map((_,i)=>inf(40+i*31,250,1.1,t)).join("") + `<path d="M0 262H480" stroke="${t}" stroke-opacity=".4"/>`,
