"master-the-sciences": t => orbit(240,135,30,[TC.red,TC.red,TC.blue,TC.blue,TC.green,TC.green,TC.yellow,TC.yellow].map((c,i)=>techCard(f1(240+Math.cos(i*.785)*90),f1(135+Math.sin(i*.785)*90),c,{s:1.05})).join("")) + `<circle cx="240" cy="135" r="30" fill="${t}" opacity=".25" class="a-grow"/><circle cx="240" cy="135" r="12" fill="#fff" class="a-pulse"/>`,
