const arcPts = (n, cx, cy, rx, ry, a0 = 200, a1 = 340) => [...Array(n)].map((_, i) => { const a = (a0 + (a1 - a0) * (n === 1 ? .5 : i / (n - 1))) * Math.PI / 180; return [f1(cx + Math.cos(a) * rx), f1(cy + Math.sin(a) * ry)]; });
const glow = (x, y, r, c, o = .35) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" opacity="${o}" class="a-grow"/>`;
const lightUp = (inner, dl) => `<g class="a-light" style="animation-delay:${dl}s">${inner}</g>`;
function galaxy(cx, cy, r, c){ const rr = rnd(7); let s = `<g class="a-spin" style="transform-origin:${cx}px ${cy}px;transform-box:view-box;animation-duration:120s">`;
  for (let arm = 0; arm < 2; arm++) for (let i = 0; i < 70; i++) { const tt = i / 70, a = arm * Math.PI + tt * 5.2, d = tt * r; s += `<circle cx="${f1(cx + Math.cos(a) * d + (rr() - .5) * 10)}" cy="${f1(cy + Math.sin(a) * d * .45 + (rr() - .5) * 6)}" r="${f1(.6 + rr() * 1.3)}" fill="${i % 9 ? "#cfe0ff" : c}" opacity="${f1(.35 + rr() * .5)}"/>`; }
  return s + `</g><ellipse cx="${cx}" cy="${cy}" rx="${f1(r * .3)}" ry="${f1(r * .14)}" fill="#fff3cf" opacity=".28" class="a-grow"/>`; }
