function outpost(x,y,s,c){ return `<g transform="translate(${x} ${y}) scale(${s})"><ellipse cy="1" rx="16" ry="3" fill="#000" opacity=".5"/><path d="M-13 0A13 11 0 0 1 13 0Z" fill="url(#gx-steel)"/><path d="M-13 0A13 11 0 0 1 13 0" fill="none" stroke="${c}" stroke-width="1.2"/><rect x="-2" y="-18" width="4" height="8" fill="url(#gx-steel)"/><circle cy="-20" r="2.6" fill="${c}" filter="url(#gx-bloom)" class="a-pulse"/>${[-7,0,7].map(xx=>`<rect x="${xx-1}" y="-5" width="2" height="2" fill="#ffe7a8"/>`).join("")}</g>`; }
function ruin(x,y,s,c){ return `<g transform="translate(${x} ${y}) scale(${s})"><ellipse cy="2" rx="26" ry="4" fill="#000" opacity=".5"/>${[[-18,30],[-8,40],[2,22],[12,36],[22,18]].map(([xx,h])=>`<rect x="${xx-3}" y="${-h}" width="6" height="${h}" fill="url(#gx-steel)" opacity=".85"/><rect x="${xx-4}" y="${-h-2}" width="8" height="3" fill="#cfc6b4"/>`).join("")}<path d="M-24 -40H6" stroke="#cfc6b4" stroke-width="4"/><circle cx="-6" cy="-22" r="5" fill="${c}" filter="url(#gx-bloom)" class="a-pulse"/><path d="M-6 -22l3 -6 3 6 -3 6z" fill="#fff"/></g>`; }
function scan(x,y,ang,len,c){ return `<g transform="translate(${x} ${y}) rotate(${ang})"><g class="a-scan"><path d="M0 0L${len} -${f1(len*.28)}L${len} ${f1(len*.28)}Z" fill="${c}" opacity=".18"/><path d="M0 0L${len} 0" stroke="${c}" stroke-width="1" opacity=".6"/></g></g>`; }
function holo(x,y,w,h,c){ return `<g class="a-pulse" style="animation-duration:3.4s"><path d="M${x} ${y+h+30}L${x-w/2} ${y+h}H${x+w/2}Z" fill="${c}" opacity=".12"/><rect x="${x-w/2}" y="${y}" width="${w}" height="${h}" rx="4" fill="${c}" opacity=".08" stroke="${c}" stroke-opacity=".5"/>${[...Array(Math.floor(h/6))].map((_,i)=>`<line x1="${x-w/2+3}" y1="${y+3+i*6}" x2="${x+w/2-3}" y2="${y+3+i*6}" stroke="${c}" stroke-opacity=".12"/>`).join("")}</g>`; }
function drop(inner, dy, dur, dl){ return `<g class="a-fly" style="--fx:0px;--fy:${dy}px;animation-duration:${dur}s;animation-delay:${dl}s">${inner}</g>`; }
function lane(id, d, c, items, dur = 6){ return `<path d="${d}" fill="none" stroke="${c}" stroke-width="5" opacity=".25" filter="url(#gx-bloom)"/><path d="${d}" fill="none" stroke="${mix(c,"#ffffff",.4)}" stroke-width="1.2" stroke-dasharray="3 7" class="a-dash"/>` + items.map((it, i) => `<g style="offset-path:path('${d}');offset-rotate:auto;animation:aPath ${dur}s linear infinite;animation-delay:-${f1(i*dur/items.length)}s">${it}</g>`).join(""); }

