/* ======== Battle Arbiter unit models (sprites rendered from the 3D minis), tinted per color ======== */
const TINTS = {};
function tint(c){ const key = c.replace("#",""); if (!TINTS[key]) { TINTS[key] = 1; if (typeof document !== "undefined") { const add = () => { const defs = document.querySelector("#gx-defs defs"); if (defs && !document.getElementById("tint-" + key)) defs.insertAdjacentHTML("beforeend", `<filter id="tint-${key}" color-interpolation-filters="sRGB" x="-5%" y="-5%" width="110%" height="110%"><feFlood flood-color="${c}"/><feComposite in2="SourceGraphic" operator="arithmetic" k1="1.25" k2="0" k3="0.2" k4="0"/><feComposite in2="SourceGraphic" operator="in"/></filter>`); }; if (document.querySelector("#gx-defs defs")) add(); else document.addEventListener("DOMContentLoaded", add); } } return `url(#tint-${key})`; }
const ENEMY = new Set([FOE, FOE2]);
const unitCol = c => ENEMY.has(c) ? mix(c, "#ffd0c8", .15) : mix("#cdd8ee", c, .18);
const SPR = {flag:["fs",60,91/220,[[-.16,1.3],[.16,1.3],[0,1.6]]], dread:["dn",52,92/220,[[-.2,1.1],[.2,1.1]]], carrier:["cv",46,79/220,[[-.22,1],[.22,1]]], cruiser:["ca",42,68/220,[[0,1.1]]], destroyer:["dd",32,98/160,[[0,.9]]], fighter:["ff",15,144/160,[[0,.5]]]};
const UIMG = (k, x, y, w, h, c, cls) => `<image href="art/units/${k}.webp" x="${f1(x)}" y="${f1(y)}" width="${f1(w)}" height="${f1(h)}" filter="${tint(unitCol(c))}"${cls ? ` class="${cls}"` : ""}/>`;
ship = function(type,x,y,s,c,rot=0,o={}){
  if (type === "warsun") return warsun(x,y,s,c,o);
  const [k, w, ar, eng] = SPR[type]; const h = w * ar, ec = mix(c, "#7fe8ff", .55);
  const glow = eng.map(([ey, r]) => `<ellipse cx="${f1(-w/2 - r*4)}" cy="${f1(ey*h)}" rx="${f1(r*6)}" ry="${f1(r*1.8)}" fill="${ec}" opacity=".8" filter="url(#gx-bloom)" class="a-flick"/><ellipse cx="${f1(-w/2 - r)}" cy="${f1(ey*h)}" rx="${f1(r*2)}" ry="${f1(r*.9)}" fill="#effdff"/>`).join("");
  return `<g transform="translate(${x} ${y}) rotate(${rot}) scale(${s})"><g${o.cls?` class="${o.cls}"`:""}${o.dl!=null?D(0,o.dl):""}>${glow}<ellipse cx="0" cy="${f1(h*.55)}" rx="${f1(w*.45)}" ry="${f1(h*.18)}" fill="#000" opacity=".25" filter="url(#gx-bloom)"/>${UIMG(k, -w/2, -h/2, w, h, c)}</g></g>`;
};
warsun = function(x,y,s,c,o={}){ const h = 44, w = h*183/220;
  return `<g transform="translate(${x} ${y}) scale(${s})"><g${o.cls?` class="${o.cls}"`:""}><circle r="30" fill="#ff8a3a" opacity=".28" filter="url(#gx-bloom2)"/>${UIMG("ws", -w/2, -h/2, w, h, c)}<circle r="4" fill="#ffe7a0" opacity=".85" filter="url(#gx-bloom)" class="a-pulse"/></g></g>`; };
mech = function(x,y,s,c,o={}){ const h = 30, w = h*143/160;
  return `<g transform="translate(${x} ${y}) scale(${s})"><g${o.cls?` class="${o.cls}"`:""}${o.dl!=null?D(0,o.dl):""}><ellipse cy="6" rx="13" ry="2.6" fill="#000" opacity=".45"/>${UIMG("mech", -w/2, 7-h, w, h, c)}</g></g>`; };
inf = function(x,y,s,c,o={}){ const h = 24, w = h*160/152;
  return `<g transform="translate(${x} ${y}) scale(${s})"><g${o.cls?` class="${o.cls}"`:""}${o.dl!=null?D(0,o.dl):""}><ellipse cy="11" rx="9" ry="2" fill="#000" opacity=".45"/>${UIMG("inf", -w/2, 12-h, w, h, c)}</g></g>`; };
pds = function(x,y,s,c,rot=-35){ const h = 26, w = h*135/159, flip = (rot < -90 || rot > 90);
  return `<g transform="translate(${x} ${y}) scale(${flip ? -s : s} ${s})"><ellipse cy="0" rx="11" ry="2.4" fill="#000" opacity=".45"/>${UIMG("pds", -w/2, 1-h, w, h, c)}<circle cx="${f1(w*.32)}" cy="${f1(1-h*.88)}" r="2.2" fill="#9fe8ff" filter="url(#gx-bloom)" class="a-pulse"/></g>`; };
