  (t,o) => ship("dread",240,135,4.2,t) + `<g class="a-flick">${boom(200,120,10,0)}${boom(285,150,8,.6)}</g>` + `<circle cx="240" cy="135" r="95" fill="none" stroke="#62d08a" stroke-width="3" class="a-ping"/><circle cx="240" cy="135" r="95" fill="none" stroke="#62d08a" stroke-width="8" opacity=".25" filter="url(#gx-bloom)" class="a-ping" style="animation-delay:.4s"/>`,
  (t,o) => [1,2,3,4,5,6,7,8].map((n,i)=>{const c=["#e5483d","#f28c28","#f2d14b","#3fbf6f","#2bb5a8","#4f9dff","#3a63d6","#9b59d0"][i];const sx=40+i*57;return fly(`<g transform="translate(${sx} 230)"><rect x="-20" y="-30" width="40" height="60" rx="5" fill="${mix(c,"#000000",.6)}" stroke="${c}" stroke-width="2"/><text y="8" text-anchor="middle" font-family="Oxanium,sans-serif" font-weight="700" font-size="24" fill="${c}">${n}</text></g>`,0,-120,3.2,i*.15)}).join("")
