function bigFace(x, y, c, title, sub, o = {}){ const s = o.s || 1, w = o.w || 96, h = o.h || 136;
  return `<g transform="translate(${x} ${y}) rotate(${o.rot || 0}) scale(${s})"><g${o.cls ? ` class="${o.cls}"` : ""}${o.dl != null ? D(0, o.dl) : ""}>
<rect x="${-w/2-3}" y="${-h/2-3}" width="${w+6}" height="${h+6}" rx="8" fill="${c}" opacity=".35" filter="url(#gx-bloom)"/>
<rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="7" fill="url(#gx-card)" stroke="${mix(c,"#ffffff",.3)}" stroke-width="1.6"/>
<rect x="${-w/2}" y="${-h/2}" width="${w}" height="22" rx="7" fill="${c}"/><rect x="${-w/2}" y="${-h/2}" width="${w}" height="22" rx="7" fill="url(#gx-hull)"/>
<text x="0" y="${-h/2+15}" text-anchor="middle" font-family="Oxanium,sans-serif" font-weight="700" font-size="10" letter-spacing="1" fill="#0a0d16">${title}</text>
${o.art || `<rect x="${-w/2+8}" y="${-h/2+28}" width="${w-16}" height="${h*.32}" rx="4" fill="${c}" opacity=".35"/><rect x="${-w/2+8}" y="${-h/2+28}" width="${w-16}" height="${h*.32}" rx="4" fill="url(#gx-sphere)"/>`}
<rect x="${-w/2+6}" y="${h*.08}" width="${w-12}" height="14" rx="3" fill="#ffd27a" opacity=".22" class="a-pulse"/>
<text x="${-w/2+10}" y="${h*.08+10.5}" font-family="Oxanium,sans-serif" font-weight="700" font-size="9.5" fill="#ffd27a">${sub || "ACTION:"}</text>
${[0,1,2].map(i => `<path d="M${-w/2+10} ${h*.08+24+i*9}h${w-20-(i==2?22:0)}" stroke="${c}" stroke-opacity=".6"/>`).join("")}</g></g>`; }
const CT_SC = [
  t => [0,1,2,3].map(i => card(150+i*55, 205, ["#ff6a5a","#ff6a5a","#ff6a5a","#ff6a5a"][i], {s:1.3, rot:(i-1.5)*10})).join("") + bigFace(240, 110, "#ff6a5a", "ACTION CARD", "ACTION:", {cls:"a-bob"}) + `<path d="M296 121h36" stroke="#ffd27a" stroke-width="1.4" opacity=".7"/><path d="M300 116l-6 5 6 5" fill="none" stroke="#ffd27a" stroke-width="1.4"/><text x="338" y="118" font-family="JetBrains Mono,monospace" font-size="11" fill="#ffd27a">look for</text><text x="338" y="132" font-family="JetBrains Mono,monospace" font-size="11" fill="#ffd27a">"Action:"</text>`,
  t => bigFace(170, 135, "#4f8dff", "TECHNOLOGY", "ACTION: Exhaust", {art:`<g transform="translate(0 -18)"><path d="M-22 0h14v10h20M-22 16h10v8h24M14 0v-8" fill="none" stroke="#4f8dff" stroke-width="1.6"/><circle cx="14" cy="10" r="4" fill="#fff"/></g>`}) + `<g transform="translate(340 135)"><g class="a-ready">${bigFace(0, 0, "#4f8dff", "TECHNOLOGY", "ACTION: Exhaust", {s:.85})}</g></g>` + `<text x="340" y="250" text-anchor="middle" font-family="JetBrains Mono,monospace" font-size="11" fill="#9fc1ff">exhausted after use · readies in status</text>`,
  t => bigFace(120, 135, "#62d08a", "AGENT", "ACTION: Exhaust", {s:.9}) + bigFace(240, 135, "#8a93a8", "COMMANDER", "Always on", {s:.9}) + `<g opacity=".5">${""}</g>` + bigFace(360, 135, "#f0a64a", "HERO", "ACTION: Purge", {s:.9, cls:"a-grow"}) + crown(360, 50, 1.2) + `<text x="360" y="250" text-anchor="middle" font-family="JetBrains Mono,monospace" font-size="10" fill="#f0a64a">unlocks at 3 objectives</text>`,
  t => `<g transform="translate(240 135)"><rect x="-170" y="-95" width="340" height="190" rx="12" fill="url(#gx-card)" stroke="#8be6e2" stroke-opacity=".6" stroke-width="1.6"/><circle cx="-125" cy="-50" r="30" fill="#8be6e2" opacity=".25"/><circle cx="-125" cy="-50" r="30" fill="url(#gx-sphere)"/>${[0,1,2,3,4].map(i => `<path d="M-80 ${-70+i*14}h${200-i*18}" stroke="#8be6e2" stroke-opacity=".35"/>`).join("")}<rect x="-155" y="10" width="310" height="26" rx="5" fill="#ffd27a" opacity=".2" class="a-pulse"/><text x="-145" y="28" font-family="Oxanium,sans-serif" font-weight="700" font-size="12" fill="#ffd27a">ABILITY · ACTION: Spend 1 strategy token…</text>${[0,1].map(i => `<path d="M-145 ${55+i*14}h${250-i*60}" stroke="#8be6e2" stroke-opacity=".35"/>`).join("")}<text x="0" y="-80" text-anchor="middle" font-family="Oxanium,sans-serif" font-size="11" letter-spacing="3" fill="#8be6e2">FACTION SHEET</text></g>`,
  (t, o) => ring(80, 200, 26, o[1] || FOE) + ring(400, 200, 26, o[0] || t) + `<g style="offset-path:path('M80 170 Q 240 0 400 170');animation:aPath 3.6s ease-in-out infinite alternate">${bigFace(0, 0, "#7fb5ff", "PROMISSORY", "ACTION: Place face up", {s:.75})}</g>` + `<text x="240" y="255" text-anchor="middle" font-family="JetBrains Mono,monospace" font-size="11" fill="#9fc1ff">another player's note, given to you in a deal</text>`,
  t => `<circle cx="240" cy="130" r="80" fill="#c99bff" opacity=".22" filter="url(#gx-bloom2)" class="a-grow"/>` + `<g class="a-burnup" style="animation-duration:5s">${frag(240, 125, 4.2, "#c99bff")}</g>` + bigFace(390, 140, "#c99bff", "RELIC", "ACTION: Purge", {s:.75}) + `<text x="240" y="245" text-anchor="middle" font-family="JetBrains Mono,monospace" font-size="11" fill="#d9c2ff">many relics are purged after one use</text>`,
  t => [["#5aa0ff",110],["#5aa0ff",180],["#5aa0ff",250]].map(([c, x], i) => fly(frag(x, 150, 2.4, c), 330 - x, -10, 3, i * .3)).join("") + `<circle cx="360" cy="140" r="40" fill="#ffd27a" opacity=".3" filter="url(#gx-bloom2)" class="a-pulse"/>` + crown(360, 140, 2) + `<text x="240" y="245" text-anchor="middle" font-family="JetBrains Mono,monospace" font-size="11" fill="#9fe8c0">ACTION: purge 3 matching fragments → gain a relic</text>`
];

window.ACT_SCENE = function(kind, step, tint, sc){
  const t = tint || "#8be6e2"; let b = "";
  if (kind === "tact") {
    const act = step === 0;
    b += hex(110,135,70) + hex(300,135,96,{fill:act?mix(t,"#000000",.78):"rgba(30,45,80,.28)",stroke:act?t:undefined,sw:act?2.4:1.2});
    const ctrl = step >= 8;
    b += planet(335,160,34,TR.cul);
    if (!ctrl && step < 8) b += pds(335,126,1.3,FOE2,-150);
    if (step > 0) b += cmdTok(300,60,11,t);
    const myAt = (dx=0) => ship("dread",245+dx,110,1.25,t) + ship("carrier",230+dx,165,1.1,t) + ship("cruiser",270+dx,200,1,t);
    const foe = ship("cruiser",380,85,1.2,FOE2,180) + ship("destroyer",400,115,1,FOE2,180);
    if (step === 0) b += myAt(-140) + foe + fly(cmdTok(300,-10,16,t),0,70,2.6,0) + `<circle cx="300" cy="135" r="60" fill="none" stroke="${t}" class="a-ping"/>`;
    if (step === 1) b += fly(myAt(-140),140,0,3.2,0) + foe + `<path d="M150 135H215" stroke="${t}" stroke-width="3" stroke-dasharray="6 6" class="a-dash"/><path d="M210 125l12 10-12 10" fill="none" stroke="${t}" stroke-width="3"/>`;
    if (step === 2) b += myAt() + foe + beam(330,118,250,112,FOE2,0,2.2) + beam(330,118,235,165,FOE2,.6,2.2) + boom(235,165,14,.7);
    if (step === 3) b += myAt() + foe + beam(268,110,375,86,t,0,2.2) + beam(380,86,270,108,FOE2,.5,2.2) + boom(380,86,16,.3) + boom(400,115,14,1.1);
    if (step === 4) b += myAt() + `<circle cx="335" cy="160" r="48" fill="none" stroke="#7fb5ff" stroke-dasharray="4 5" stroke-opacity=".6"/>` + beam(265,112,325,150,"#ff8a3a",0,2.6) + boom(330,152,16,.3);
    if (step === 5) b += myAt() + [0,1,2].map(i => fly(inf(245,165,1.1,t),78+i*10,-15+i*6,2.6,i*.5)).join("");
    if (step === 6) b += myAt() + inf(320,158,1.1,t) + inf(340,166,1.1,t) + beam(335,126,322,150,FOE2,0,2) + boom(322,152,9,.3);
    if (step === 7) b += myAt() + inf(318,160,1.2,t) + inf(334,166,1.2,t) + inf(350,158,1.2,FOE2) + beam(322,156,348,156,"#ffd27a",0,1.4) + boom(350,156,10,.4) + boom(334,164,8,1.2);
    if (step === 8) b += myAt() + flag(338,128,t,1.4) + inf(322,162,1.1,t) + fly(card(330,150,TR.cul,{s:.7}),90,-80,2.6,.2) + `<g transform="translate(430 60) rotate(90)"><rect x="-17" y="-24" width="34" height="48" rx="3" fill="${mix(TR.cul,"#000000",.6)}" stroke="${TR.cul}"/></g>`;
    if (step === 9) b += flag(338,128,t,1.3) + dock(335,160,3.2,t) + [0,1,2].map(i => fly(ship(["fighter","cruiser","fighter"][i],300,160,1.2,t),-60,-50+i*40,2.6,i*.7)).join("") + ship("dread",245,110,1.25,t);
  } else if (kind === "strat") {
    const c = sc ? sc.c : t;
    if (step === 0) b += bigCard(c, sc ? sc.n : "", sc ? sc.name.toUpperCase() : "", {cls:"a-grow"}) + `<circle cx="240" cy="135" r="120" fill="none" stroke="${c}" stroke-opacity=".4" class="a-ping"/>`;
    if (step === 1) { b += bigCard(c, sc ? sc.n : "", sc ? sc.name.toUpperCase() : ""); const oc = (sc && sc.others && sc.others.length) ? sc.others : [FOE,FOE2,"#3fbf6f","#a77bff","#f2d14b"]; const spots = [[70,70],[410,70],[70,200],[410,200],[150,245],[330,245],[240,25]]; oc.slice(0,7).forEach((col,i)=>{ const [x,y]=spots[i]; b += `<circle cx="${x}" cy="${y}" r="18" fill="#0b1222" stroke="${col}" stroke-width="3"/>` + fly(cmdTok(x,y,9,col),(240-x)*.6,(135-y)*.6,2.6,i*.4); }); }
    if (step === 2) b += bigCard(c, sc ? sc.n : "", sc ? sc.name.toUpperCase() : "", {cls:"a-exhaust"});
  } else if (kind === "sp") {
    const f = SP[sc && sc.n] && SP[sc.n][step]; b += f ? f(sc.c, (sc.others && sc.others.length) ? sc.others : [FOE,FOE2,"#3fbf6f","#a77bff","#f2d14b"]) : "";
  } else if (kind === "status") {
    b += STS_SC[step] ? STS_SC[step](t, (sc && sc.others) || [FOE,FOE2,"#3fbf6f","#a77bff","#f2d14b"]) : "";
  } else if (kind === "ctype") {
    b += CT_SC[step] ? CT_SC[step](t, (sc && sc.others) || [FOE, FOE2]) : "";
  } else if (kind === "comp") {
    if (step === 0) b += [0,1,2,3].map(i=>card(150+i*60,235,["#ff6a5a","#7fb5ff","#c99bff","#f2d14b"][i],{s:1.2,rot:(i-1.5)*10})).join("") + fly(card(240,215,t,{s:1.6}),0,-90,2.8,0);
    if (step === 2) b += [[card(110,140,"#ff6a5a",{s:1.7,rot:-14}),0],[techCard(185,110,"#4f8dff",{s:1.8,rot:-6}),.3],[frag(255,105,2.6,"#c99bff"),.6],[card(325,110,"#7fb5ff",{s:1.7,rot:6}),.9],[crown(395,140,2),1.2]].map(([g,d])=>bob(g,d)).join("") + `<ellipse cx="250" cy="215" rx="190" ry="20" fill="${t}" opacity=".18" filter="url(#gx-bloom2)"/>`;
    if (step === 1) b += card(240,130,t,{s:2.4}) + `<circle cx="240" cy="130" r="90" fill="none" stroke="${t}" stroke-opacity=".5" class="a-ping"/>` + [...Array(8)].map((_,i)=>fly(`<circle cx="240" cy="130" r="3" fill="${t}"/>`,Math.cos(i*.785)*120,Math.sin(i*.785)*90,2,i*.15)).join("");
  } else if (kind === "pass") {
    b += `<g class="a-bob">${cmdTok(240,130,56,t)}</g><text x="240" y="232" text-anchor="middle" font-family="Oxanium,sans-serif" font-weight="700" font-size="22" letter-spacing="6" fill="${t}">PASSED</text>` + [0,1,2,3].map(i=>`<g opacity=".35">${cmdTok(90+i*100+(i>1?100:0),60,12,FOE)}</g>`).join("");
  }
  return `<svg class="sc" viewBox="0 0 480 270" preserveAspectRatio="xMidYMid meet" aria-hidden="true">${bg(t, hash(kind+step))}${b}</svg>`;
};

/* ---------- Speaker token (matches the physical enamel token) ---------- */
function speakerArt(){
  const P = "4,55 32,5 168,5 196,55 168,105 32,105", I = "16,55 39,15 161,15 184,55 161,95 39,95";
  const gear = (x, y, r) => `<g transform="translate(${x} ${y})"><circle r="${r}" fill="none" stroke="#6f757e" stroke-width="2.4"/>${[...Array(6)].map((_, i) => `<rect x="-1.6" y="${-r - 3}" width="3.2" height="4" fill="#6f757e" transform="rotate(${i * 60})"/>`).join("")}<circle r="${f1(r * .45)}" fill="#14161c"/></g>`;
  const dot = (x, y) => `<circle cx="${x}" cy="${y}" r="7.5" fill="#e3262b" stroke="#5c6068" stroke-width="1.6"/><ellipse cx="${x - 2}" cy="${y - 2.5}" rx="3" ry="1.6" fill="#ff8a8a" opacity=".7"/>`;
  return `<polygon points="${P}" fill="#a9aeb6"/><polygon points="${P}" fill="none" stroke="#5c6068" stroke-width="2"/>
<polygon points="${I}" fill="#b81c22" stroke="#5c6068" stroke-width="1.4"/>
<path d="M28 55Q100 -8 172 55" fill="none" stroke="#e3262b" stroke-width="9"/><path d="M28 55Q100 118 172 55" fill="none" stroke="#e3262b" stroke-width="9"/>
<path d="M40 34l18 8M160 34l-18 8M40 76l18 -8M160 76l-18 -8" stroke="#5c6068" stroke-width="1.4"/>
${gear(30, 55, 8)}${gear(170, 55, 8)}${gear(46, 26, 5)}${gear(154, 26, 5)}${gear(46, 84, 5)}${gear(154, 84, 5)}
<path d="M34 42Q100 30 166 42L166 68Q100 80 34 68Z" fill="#14161c" stroke="#5c6068" stroke-width="1.6"/>
${dot(66, 25)}${dot(100, 18)}${dot(134, 25)}${dot(66, 85)}${dot(100, 92)}${dot(134, 85)}
<text x="100" y="63" text-anchor="middle" font-family="Oxanium,Eurostile,sans-serif" font-weight="700" font-size="22" letter-spacing="1" fill="#f2f4f8" stroke="#5c6068" stroke-width=".6">SPEAKER</text>`;
}
window.SPEAKER_SVG = (cls = "spk") => `<svg class="${cls}" viewBox="0 0 200 110" aria-label="Speaker token" role="img">${speakerArt()}</svg>`;
speakerTok = function(x, y, s = 1){ return `<g transform="translate(${x} ${y}) scale(${f1(s * .32)})"><g transform="translate(-100 -55)"><polygon points="4,55 32,5 168,5 196,55 168,105 32,105" fill="#e3262b" opacity=".35" filter="url(#gx-bloom2)"/>${speakerArt()}</g></g>`; };

