function cine(t, seed, body, hz){
  const v = nid("vg"), r = nid("ry"), sw = nid("sw"), hg = nid("hz");
  let h = "";
  if (hz) h = `<defs><radialGradient id="${hg}" cx="50%" cy="0%" r="100%"><stop offset="0" stop-color="${mix(hz,"#000000",.45)}"/><stop offset=".25" stop-color="${mix(hz,"#000000",.8)}"/><stop offset="1" stop-color="#020308"/></radialGradient></defs><circle cx="240" cy="760" r="540" fill="url(#${hg})"/><circle cx="240" cy="760" r="540" fill="none" stroke="${hz}" stroke-width="3" opacity=".7"/><circle cx="240" cy="760" r="546" fill="none" stroke="${hz}" stroke-width="12" opacity=".12"/>`;
  return `<defs><linearGradient id="${r}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${t}" stop-opacity=".5"/><stop offset="1" stop-color="${t}" stop-opacity="0"/></linearGradient>
<linearGradient id="${sw}" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset=".5" stop-color="#fff" stop-opacity=".13"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>
<radialGradient id="${v}" cx="50%" cy="50%" r="72%"><stop offset=".55" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".75"/></radialGradient></defs>
${bg(t, seed)}<g class="a-rays">${[[-10,0,90,0,260,300],[60,0,130,0,380,300],[120,0,170,0,470,260]].map(([a,b2,c,d,e,f]) => `<polygon points="${a},${b2} ${c},${d} ${e},${f} ${e-140},${f}" fill="url(#${r})" opacity=".14"/>`).join("")}</g>${h}
<g class="cam">${body}</g><rect class="a-sweep" x="-160" y="-40" width="120" height="360" fill="url(#${sw})" transform="rotate(18 240 135)"/><rect width="480" height="270" fill="url(#${v})" pointer-events="none"/>`;
}
window.OBJ_SCENE = function(id, tint){
  const f = S[id]; tint = tint || "#f0a64a";
  const body = f ? f(tint) : `<circle cx="240" cy="135" r="40" fill="${tint}" opacity=".3"/>`;
  return `<svg class="sc" viewBox="0 0 480 270" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${cine(tint, hash(id), body, null)}</svg>`;
};
